(()=>{'use strict';let promptEvent=null;const $=id=>document.getElementById(id);const modal=$('installModal'),info=$('installInstructions'),confirm=$('installConfirm');const ios=/iphone|ipad|ipod/i.test(navigator.userAgent);const standalone=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;function open(){if(standalone){info.textContent='Already installed! Open it from your Home Screen.';confirm.hidden=true}else if(ios){info.textContent='On iPhone or iPad: open this site in Safari, tap Share (square with upward arrow), then choose Add to Home Screen.';confirm.textContent='Got it'}else if(promptEvent){info.textContent='Install this free app on your device.';confirm.textContent='Install App'}else{info.textContent='Use your browser menu (⋮ or Share) and choose Install app or Add to Home Screen. The install option appears when supported.';confirm.textContent='Got it'}modal.hidden=false}function close(){modal.hidden=true}window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();promptEvent=e});window.addEventListener('appinstalled',()=>{promptEvent=null;close()});$('installLaunch').addEventListener('click',open);$('installClose').addEventListener('click',close);$('installLater').addEventListener('click',close);modal.addEventListener('click',e=>{if(e.target===modal)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});confirm.addEventListener('click',async()=>{if(promptEvent){const p=promptEvent;promptEvent=null;close();try{await p.prompt();await p.userChoice}catch(e){console.warn('Install prompt unavailable',e)}}else close()});if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(e=>console.warn('Offline setup failed',e)))}})();